public class WatchProtocolDecoderTest {

    @Test
    public void decode_emptyMessage() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        Object msg = new byte[0];
        Object result = decoder.decode(channel, remoteAddress, msg);
        assertNull(result);
    }

    @Test
    public void decode_singleByteMessage() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        ByteBuf data = Unpooled.buffer(1);
        data.writeByte((byte) 0x01);
        Object msg = data;
        Object result = decoder.decode(channel, remoteAddress, msg);
        assertNotNull(result);
    }

    @Test
    public void decode_twoByteMessage() throws Exception {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        Channel channel = Mockito.mock(Channel.class);
        SocketAddress remoteAddress = Mockito.mock(SocketAddress.class);
        ByteBuf data = Unpooled.buffer(2);
        data.writeBytes(new byte[]{0x01, 0x02});
        Object msg = data;
        Object result = decoder.decode(channel, remoteAddress, msg);
        assertNotNull(result);
    }

    @Test
    public void getHasIndex_emptyMessage() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        assertTrue(decoder.getHasIndex());
    }

    @Test
    public void getHasIndex_singleByteMessage() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        ByteBuf data = Unpooled.buffer(1);
        data.writeByte((byte) 0x01);
        assertTrue(decoder.getHasIndex());
    }

    @Test
    public void getHasIndex_twoByteMessage() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        ByteBuf data = Unpooled.buffer(2);
        data.writeBytes(new byte[]{0x01, 0x02});
        assertTrue(decoder.getHasIndex());
    }

    @Test
    public void getManufacturer_emptyMessage() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        assertNull(decoder.getManufacturer());
    }

    @Test
    public void getManufacturer_singleByteMessage() {
        WatchProtocolDecoder decoder = new WatchProtocolDecoder(Protocol.WATCH);
        ByteBuf data = Unpooled.buffer(1);
        data.writeByte((byte) 0x01);
        assertEquals("W", decoder.getManufacturer());
    }

